//   - 1: no common ancestor (disconnected)
//   - 128+: error (corrupt repo, invalid hash, etc.)
func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
	cmd.Dir = repoPath
	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return true, nil // No common ancestor — disconnected
		}
		return false, fmt.Errorf("git merge-base failed: %w", err)
	}
	return false, nil // Shared ancestry
}

// collectCommitChain walks from tip to root following first parent, returns oldest-first.
// Commits listed in shallow are treated as roots — the walk stops at them without
// traversing into their parents. go-git's repo.CommitObject().ParentHashes does not
// consult .git/shallow on its own, so without this check the walk would stroll past
// shallow boundaries into stale objects left in the pack (e.g., when the remote
// branch has been rebuilt since the last full fetch), producing a phantom chain of
// commits that no longer represent the actual checkpoint history.
func collectCommitChain(repo *git.Repository, tip plumbing.Hash, shallow map[plumbing.Hash]bool) ([]*object.Commit, error) {
	var chain []*object.Commit
	current := tip

	reachedRoot := false
	for range MaxCommitTraversalDepth {
		commit, err := repo.CommitObject(current)
		if err != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
		}
		chain = append(chain, commit)

		if len(commit.ParentHashes) == 0 {
			reachedRoot = true
			break
		}
		if shallow[current] {
			// Shallow boundary — treat as a root.
			reachedRoot = true
			break
		}
		current = commit.ParentHashes[0]
	}

	if !reachedRoot {
		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
	}

	// Reverse to oldest-first
	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
		chain[i], chain[j] = chain[j], chain[i]
	}

	return chain, nil
}

// loadShallowHashes returns the commit hashes listed in the repository's
// shallow file, or an empty map if the repository is not shallow.
func loadShallowHashes(ctx context.Context, repoPath string) (map[plumbing.Hash]bool, error) {
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = repoPath
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git rev-parse --git-common-dir: %w", err)
	}
	gitDir := strings.TrimSpace(string(out))
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(repoPath, gitDir)
	}
	// Through the common dir's root like every other read there. "shallow" is a
	// fixed name and gitDir came from git's own --git-common-dir, so nothing here
	// can traverse today; the root is what keeps that true without depending on
	// it, and it shares the one handle per clone.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return nil, fmt.Errorf("open git common dir: %w", err)
	}
	data, err := osroot.ReadFileNoFollow(root, "shallow")
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return map[plumbing.Hash]bool{}, nil
		}
		return nil, fmt.Errorf("read shallow file: %w", err)
	}
	set := map[plumbing.Hash]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		set[plumbing.NewHash(line)] = true
	}
	return set, nil
}

// cherryPickOnto applies each commit's delta onto base, building a linear chain.
// For each commit, it computes the full diff from its parent (additions, modifications,
// and deletions), then applies that delta onto the current tip's tree.
//
// Commits listed in shallow are treated as roots: their delta is computed against
// an empty tree rather than against their (past-the-boundary) parent. Without this,
// a shallow-boundary commit would be diffed against a stale parent tree whose
// objects live in the local pack but no longer represent the actual checkpoint
// history — producing nonsense changes when replayed onto the remote tip.
func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit, shallow map[plumbing.Hash]bool) (plumbing.Hash, error) {
	currentTip := base

	for _, commit := range commits {
		changes, err := treeChangesForCherryPick(ctx, repo, commit, shallow)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		if len(changes) == 0 {
			continue // Skip no-op commits
		}

		tipCommit, err := repo.CommitObject(currentTip)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
		}

		mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
		}
		if mergedTreeHash.Equal(tipCommit.TreeHash) {
			continue
		}

		// Create new commit on top of current tip, preserving original message/author
		newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
		}

		currentTip = newHash
	}

	return currentTip, nil
}

func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit, shallow map[plumbing.Hash]bool) ([]checkpoint.TreeChange, error) {
	commitTree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
	}

	var parentTree *object.Tree
	// Shallow-boundary commits are treated as roots — see cherryPickOnto for why.
	if len(commit.ParentHashes) > 0 && !shallow[commit.Hash] {
		parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
		if pErr != nil {
			return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
		}
		parentTree, err = parentCommit.Tree()
		if err != nil {
			return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
		}
	}

	changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
	if err != nil {
		return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
	}

	treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
	for _, change := range changes {
		treeChange, changeErr := changeToTreeChange(change)
		if changeErr != nil {
			return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
		}
		treeChanges = append(treeChanges, treeChange)
	}
	return treeChanges, nil
}

func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
	action, err := change.Action()
	if err != nil {
		return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
	}

	switch action {
	case merkletrie.Insert, merkletrie.Modify:
		entry := change.To.TreeEntry
		return checkpoint.TreeChange{
			Path: change.To.Name,
			Entry: &object.TreeEntry{
				Name: entry.Name,
				Mode: entry.Mode,
				Hash: entry.Hash,
			},
		}, nil
	case merkletrie.Delete:
		return checkpoint.TreeChange{Path: change.From.Name}, nil
	default:
		return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
	if err != nil {
		return fmt.Errorf("failed to open repository for %s promote: %w", label, err)
	}
	defer repo.Close()
	defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort

	tmpRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		return fmt.Errorf("%s not found after fetch (tmp ref %s missing): %w", label, tmpRefName, err)
	}
	if err := SafelyAdvanceLocalRef(ctx, repo, destRefName, tmpRef.Hash()); err != nil {
		return fmt.Errorf("failed to advance local %s: %w", label, err)
	}
	return nil
}

// SafelyAdvanceLocalRef updates localRefName to include targetHash without
// dropping local-only commits. Missing and behind refs advance to targetHash;
// already-current or locally-ahead refs are left unchanged; diverged refs replay
// commits after the merge-base onto targetHash and move localRefName to the
// replayed tip. If there is no merge-base and the reachable histories are
// complete, the full local chain is replayed.
func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
	currentLocal, localErr := repo.Reference(localRefName, true)
	if localErr != nil {
		if !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
			return fmt.Errorf("failed to read local ref %s: %w", localRefName, localErr)
		}
		return setRefHash(repo, localRefName, targetHash)
	}

	localHash := currentLocal.Hash()
	if localHash == targetHash {
		return nil
	}

	repoPath, err := getRepoPath(repo)
	if err != nil {
		return fmt.Errorf("failed to get repo path: %w", err)
	}

	mergeBase, err := getMergeBase(ctx, repoPath, localHash.String(), targetHash.String())
	if errors.Is(err, errNoMergeBase) {
		shallow, shallowErr := hasReachableShallowBoundary(ctx, repo, repoPath, localHash.String(), targetHash.String())
		if shallowErr != nil {
			return fmt.Errorf("failed to check shallow history for %s: %w", localRefName, shallowErr)
		}
		if shallow {
			return fmt.Errorf("no merge base for %s, and reachable shallow history prevents proving refs are disconnected; run 'entire doctor' or 'git fetch --unshallow' and try again", localRefName)
		}
		return replayDisconnectedLocalRef(ctx, repo, repoPath, localRefName, localHash, targetHash)
	}
	if err != nil {
		return fmt.Errorf("failed to find merge base for %s: %w", localRefName, err)
	}
	if mergeBase == targetHash {
		return nil
	}
	if mergeBase == localHash {
		return setRefHash(repo, localRefName, targetHash)
	}

	return replayLocalRefFromBase(ctx, repo, repoPath, localRefName, localHash, targetHash, mergeBase)
}

func replayLocalRefFromBase(ctx context.Context, repo *git.Repository, repoPath string, localRefName plumbing.ReferenceName, localHash, targetHash, baseHash plumbing.Hash) error {
	localCommits, err := collectCommitsSince(ctx, repo, repoPath, localHash, baseHash)
	if err != nil {
		return fmt.Errorf("failed to collect local replay commits for %s: %w", localRefName, err)
	}
	shallow, err := loadShallowHashes(ctx, repoPath)
	if err != nil {
		return fmt.Errorf("failed to load shallow boundaries for %s: %w", localRefName, err)
	}
	return replayLocalCommits(ctx, repo, "diverged", localRefName, localHash, targetHash, localCommits, shallow)
}

func replayDisconnectedLocalRef(ctx context.Context, repo *git.Repository, repoPath string, localRefName plumbing.ReferenceName, localHash, targetHash plumbing.Hash) error {
	shallow, err := loadShallowHashes(ctx, repoPath)
	if err != nil {
		return fmt.Errorf("failed to load shallow boundaries for %s: %w", localRefName, err)
	}
	localCommits, err := collectCommitChain(repo, localHash, shallow)
	if err != nil {
		return fmt.Errorf("failed to collect disconnected local commits for %s: %w", localRefName, err)
	}
	return replayLocalCommits(ctx, repo, "disconnected", localRefName, localHash, targetHash, localCommits, shallow)
}

func replayLocalCommits(ctx context.Context, repo *git.Repository, reason string, localRefName plumbing.ReferenceName, localHash, targetHash plumbing.Hash, localCommits []*object.Commit, shallow map[plumbing.Hash]bool) error {
	// Logged here rather than in each caller: this is the function that performs
	// the rewrite, so a future third caller cannot silently skip the trace.
	//
	// A replay rewrites the local ref to the fetched remote tip with the local
	// commits re-applied on top: no checkpoint is lost, but the ref no longer
	// points where it did and the local commits have new hashes. That is the one
	// place a fetch reaches past remote-tracking refs into local state, so it must
	// leave a trace — the whole advance/replay chain was previously silent, which
	// made an invisible rewrite impossible to reconstruct afterwards from
	// .entire/logs/. Info rather than Debug: the default log level has to carry it
	// for a post-hoc investigation to find it.
	//
	// Metadata only (ref names, hashes, counts) per the logging privacy rule.
	logging.Info(ctx, "replaying local commits onto fetched tip; local ref will be rewritten",
		slog.String("reason", reason),
		slog.String("ref", localRefName.String()),
		slog.String("local_tip", localHash.String()),
		slog.String("target_tip", targetHash.String()),
		slog.Int("commits_replayed", len(localCommits)))

	if len(localCommits) == 0 {
		return setRefHash(repo, localRefName, targetHash)
	}

	newTip, err := cherryPickOnto(ctx, repo, targetHash, localCommits, shallow)
	if err != nil {
		return fmt.Errorf("failed to replay local commits for %s: %w", localRefName, err)
	}

	return setRefHash(repo, localRefName, newTip)
}

func hasReachableShallowBoundary(ctx context.Context, repo *git.Repository, repoPath string, hashes ...string) (bool, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	shallowHashes, err := repo.Storer.Shallow()
	if err != nil {
		return false, fmt.Errorf("read shallow commits: %w", err)
	}
	if len(shallowHashes) == 0 {
		return false, nil
	}

	shallowCommits := make(map[string]struct{}, len(shallowHashes))
	for _, hash := range shallowHashes {
		shallowCommits[hash.String()] = struct{}{}
	}
	for _, hash := range hashes {
		reachesBoundary, err := historyReachesShallowBoundary(ctx, repoPath, hash, shallowCommits)
		if err != nil {
			return false, err
		}
		if reachesBoundary {
			return true, nil
		}
	}
	return false, nil
}

func historyReachesShallowBoundary(ctx context.Context, repoPath, hash string, shallowCommits map[string]struct{}) (bool, error) {
	cmd := exec.CommandContext(ctx, "git", "rev-list", hash)
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return false, fmt.Errorf("git rev-list %s failed: %w", hash, err)
	}
	for _, commitHash := range strings.Fields(string(output)) {
		if _, ok := shallowCommits[commitHash]; ok {
			return true, nil
		}
	}
	return false, nil
}

func setRefHash(repo *git.Repository, refName plumbing.ReferenceName, hash plumbing.Hash) error {
	newRef := plumbing.NewHashReference(refName, hash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update local ref %s: %w", refName, err)
	}
	return nil
}

