		return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
	}

	// git-branch primary: entire/checkpoints/v1 is a real refs/heads branch, so
	// on an otherwise-empty remote a forge like GitHub would select it as the
	// default. Defer publication until the user's own branch exists there.
	deferAutomaticCheckpointPush := protectFirstUserBranch && deferCheckpointPushOnEmptyRemote(ctx, ps)

	refs := checkpoint.ResolveRefs(ctx)
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		logging.Warn(ctx, "checkpoint policy pre-push: failed to open repository; allowing checkpoint push",
			slog.String("error", repoErr.Error()),
		)
	} else {
		defer repo.Close()
		syncCheckpointPolicyForPrePush(ctx, repo, ps)
		if !checkpointPolicyAllowsGitHook(ctx, repo) {
			// Policy failures should skip checkpoint pushes, not abort the user's push.
			return nil
		}
		if err := prepareOversizedV1ForPush(
			ctx, repo, ps.pushTarget(), OversizedCheckpointMetadataThreshold,
		); err != nil {
			logging.Warn(ctx, "checkpoint metadata cleanup failed; continuing without it",
				slog.String("error", err.Error()),
			)
		}
	}

	// OPF pre-push rewrite: if OPF is configured, resolve the user's
	// decision (env > settings > prompt > non-TTY auto-run), then
	// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
	// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
	// so the common-case fast path is unchanged.
	if redact.OPFEnabled() {
		decision, decisionErr := opfPrePushDecision(ctx)
		if decisionErr != nil {
			logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
				slog.String("error", decisionErr.Error()),
			)
			return decisionErr
		}
		switch decision {
		case OPFAbort:
			return ErrOPFAbortedByUser
		case OPFSkip:
			// User opted out for this push (or settings/env say
			// "never"). Push regex-only (8-layer) content as-is.
			logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
		case OPFRun:
			_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite")
			if repoErr != nil {
				opfSpan.RecordError(repoErr)
				opfSpan.End()
				logging.Warn(ctx, "OPF pre-push: failed to open repo; aborting push",
					slog.String("error", repoErr.Error()),
				)
				return repoErr
			}
			if _, rewriteErr := RewriteUnpushedV1WithOPF(ctx, repo, ps.pushTarget()); rewriteErr != nil {
				opfSpan.RecordError(rewriteErr)
				opfSpan.End()
				logging.Warn(ctx, "OPF pre-push rewrite failed; aborting push",
					slog.String("error", rewriteErr.Error()),
				)
				return rewriteErr
			}
			opfSpan.End()
		}
	}

	if deferAutomaticCheckpointPush {
		// Do this only after OPF has had a chance to rewrite v1: the outer
		// user push may explicitly include the metadata branch.
}

// rawByteCapMultiplier ties the raw-byte RAM ceiling to the leaf-byte
// inference cap. 100× means: leaf cap 2 MiB → raw ceiling 200 MiB.
// Picked to comfortably exceed any realistic JSON-scaffolding ratio
// (a 10 MiB JSONL with 300 KB of leaves still fits) while preventing
// pathological RAM blowups (a 5 GiB pasted dump aborts before loading).
const rawByteCapMultiplier = 100

// RewriteUnpushedV1WithOPF re-redacts unpushed entire/checkpoints/v1
// commits with OPF, builds new commits carrying Entire-OPF-Applied:
// true, and CAS-updates the local ref. Idempotent: already-applied
// commits are re-parented without re-running OPF.
//
// Caller checks redact.OPFEnabled() and skips this when OPF is off.
// Returns one of {V1DivergedError, BootstrapTooLargeError,
// V1RefMovedError, OPFRuntimeFailedError, OPFNoCategoriesError,
// OPFBatchTooLargeError, OPFRawBytesTooLargeError} for
// privacy-critical failures — the pre-push hook propagates these so
// git push aborts.
func RewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	return rewriteUnpushedV1WithOPF(ctx, repo, target, OversizedCheckpointMetadataThreshold)
}

func rewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string, metadataThreshold int64) (plumbing.Hash, error) {
	localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
	}
	if localTip.IsZero() {
		return plumbing.ZeroHash, nil // no checkpoints yet
	}
	remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
	}

	reconciledTip, handled, reconcileErr := reconcileOversizedV1ForPush(
		ctx, repo, localTip, remoteTip, metadataThreshold,
	)
	if reconcileErr != nil {
		return plumbing.ZeroHash, fmt.Errorf("reconcile oversized checkpoint metadata: %w", reconcileErr)
	}
	if handled {
		localTip = reconciledTip
	}

	if !remoteTip.IsZero() {
		mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
		if mbErr != nil {
			return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
		}
		if mergeBase != remoteTip {
			return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
		}
	}

	unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
	}
	if len(unpushed) == 0 {
		return localTip, nil
	}
	if remoteTip.IsZero() {
		if limit := resolveBootstrapLimit(); len(unpushed) > limit {
			return plumbing.ZeroHash, &BootstrapTooLargeError{Count: len(unpushed), Limit: limit}
		}
	}

	// Fail-closed defense: enabled-with-no-categories means the model
	// scan can't run at all. The decision resolution in prePush already
	// rejects this state before any prompt; this second gate covers
	// direct callers and sits before the breaker check so the user gets
	// the config-specific remediation rather than OPFRuntimeFailedError's
	// "verify your OPF install".
	if redact.OPFMisconfiguredNoCategories() {
		return plumbing.ZeroHash, &OPFNoCategoriesError{}
	}

	// Fail-closed defense: if OPF is already broken at the start of
	// this push (an earlier process step tripped the breaker), abort
	// before tagging any commits as OPF-applied. Without this, the
	// per-blob fallback inside the no-OPF cases of BatchBytesWithPrivacyFilter
	// could let regex-only content slip out with the trailer attached.
	if redact.OPFBreakerTripped() {
		return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
	}

	// Pass 1: collect every redactable blob from every unpushed commit
	// that still needs OPF. Already-applied commits get re-parented
	// later without collecting (their tree stays as-is). We also track
	// each blob's source commit + tree path so we can route the redacted
	// bytes back during apply.
	type pendingCommit struct {
		commit *object.Commit
		// blobs and paths are parallel slices; len(paths)==len(blobs).
		// startIdx is this commit's offset into the global redacted slice.
		blobs    []redact.NamedBlob
		paths    []string
		startIdx int
// (e.g. both sides rewrote the root metadata.json) surfaces as a rebase error and
// the ref is left for a later pre-push. Returns nil only if the ref reached the
// remote.
func pushCheckpointRefWithRecovery(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	// One shared budget across the initial push, fetch+replay, and retry, matching
	// doPushRef (fetchAndRebaseRefCommon relies on the caller's deadline).
	ctx, cancel := context.WithTimeout(ctx, checkpointPushBudget)
	defer cancel()

	if err := batchPushRefs(ctx, target, []plumbing.ReferenceName{ref}); err == nil {
		return nil
	}
	if err := fetchAndRebaseRefCommon(ctx, target, ref); err != nil {
		return fmt.Errorf("sync diverged checkpoint ref %s: %w", ref, err)
	}
	return batchPushRefs(ctx, target, []plumbing.ReferenceName{ref})
}

// pushRefIfNeeded pushes a ref to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// For branch refs, the "has unpushed" optimization consults the remote-tracking
// ref. Non-branch refs and URL targets skip the optimization and let git
// handle the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushRefIfNeeded(ctx context.Context, target string, ref plumbing.ReferenceName) (delivered bool, err error) {
	return pushRefIfNeededWithMetadataThreshold(ctx, target, ref, OversizedCheckpointMetadataThreshold)
}

func pushRefIfNeededWithMetadataThreshold(ctx context.Context, target string, ref plumbing.ReferenceName, metadataThreshold int64) (delivered bool, err error) {
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Debug(ctx, "push skipped: open repository failed",
			slog.String("ref", ref.String()),
			slog.String("error", err.Error()))
		return false, nil
	}
	defer repo.Close()

	localRef, err := repo.Reference(ref, true)
	if err != nil {
		// Ref doesn't exist locally — nothing to push, and nothing delivered.
		// Reporting false rather than "vacuously delivered" keeps a caller that
		// gates on delivery from acting on a ref that never existed.
		return false, nil
	}

	if ref.IsBranch() && !remote.IsURL(target) && !hasUnpushedBranchRef(repo, target, localRef.Hash(), ref.Short()) {
		// Local matches the target's tracking ref: the data is already there,
		// which is delivery as far as any caller can tell.
		return true, nil
	}

	return doPushRefWithMetadataThreshold(ctx, target, ref, metadataThreshold)
}

// hasUnpushedBranchRef checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedBranchRef(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return !localHash.Equal(remoteRef.Hash())
}

func displayPushTarget(target string) string {
	if remote.IsURL(target) {
		return "checkpoint remote"
	}
	return target
}

// checkpointPushBudget is one shared deadline across the initial push,
// fetch+rebase, and retry — per-attempt timeouts can stack to ~3x. var so tests
// can shrink it.
var checkpointPushBudget = 2 * time.Minute

// doPushRef pushes the given ref to the target with fetch+rebase recovery.
// The target can be a remote name or a URL.
//
// The error return is fail-soft by design and is nil on every push failure: a
// checkpoint that cannot be synced must never break the user's own `git push`.
// That makes err useless as a "did it land" signal, so delivery is reported
// separately — delivered is true only where finishPush runs, meaning the ref is
// on the target (freshly pushed or already up-to-date). Callers that act on
// delivery, such as latching the captured checkpoint sync remote, must read
// delivered and not err.
func doPushRef(ctx context.Context, target string, ref plumbing.ReferenceName) (delivered bool, err error) {
	return doPushRefWithMetadataThreshold(ctx, target, ref, OversizedCheckpointMetadataThreshold)
}

func doPushRefWithMetadataThreshold(ctx context.Context, target string, ref plumbing.ReferenceName, metadataThreshold int64) (delivered bool, err error) {
	ctx, cancel := context.WithTimeout(ctx, checkpointPushBudget)
	defer cancel()

	displayTarget := displayPushTarget(target)
	refLabel := refDisplayName(ref)

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", refLabel, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	result, err := tryPushRefCommon(ctx, target, ref)
	if err == nil {
		finishPush(ctx, stop, result, target)
		return true, nil
	}
	stop("")

	// Protected refs cannot be fixed by syncing and retrying.
	var protectedErr *protectedRefError
	if errors.As(err, &protectedErr) {
		printProtectedRefBlock(os.Stderr, refLabel, target)
		return false, nil
	}

	// Non-interactive SSH (pre-push BatchMode): auth failures cannot be fixed by
	// fetch+rebase, and retrying would just reprint the same opaque error.
	// Surface an actionable ssh-agent hint and skip recovery (issue #1523).
	if nonInteractiveSSHAuthFailure(ctx, err) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't push %s: %v\n", refLabel, err)
		printNonInteractiveSSHAuthHint()
		printCheckpointRemoteHint(target)
		return false, nil
	}

	// Push failed - likely non-fast-forward. Try to fetch and rebase.
	// Spanned (with the network fetch as a child) so the trace distinguishes
	// "the raw push is slow" from "we keep hitting contention and re-syncing".
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", refLabel)
	stop = startProgressDots(os.Stderr)

	frCtx, fetchRebaseSpan := perf.Start(ctx, "fetch_and_rebase")
	syncErr := fetchAndRebaseRefWithMetadataThreshold(frCtx, target, ref, metadataThreshold)
	fetchRebaseSpan.RecordError(syncErr)
	fetchRebaseSpan.End()
	if syncErr != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", refLabel, syncErr)
		if nonInteractiveSSHAuthFailure(ctx, syncErr) {
			printNonInteractiveSSHAuthHint()
		}
		printCheckpointRemoteHint(target)
		return false, nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after rebase
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", refLabel, displayTarget)
	stop = startProgressDots(os.Stderr)

	result, retryErr := tryPushRefCommon(ctx, target, ref)
	if retryErr != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", refLabel, retryErr)
		if nonInteractiveSSHAuthFailure(ctx, retryErr) {
			printNonInteractiveSSHAuthHint()
		}
		printCheckpointRemoteHint(target)
		return false, nil
	}
	finishPush(ctx, stop, result, target)
	return true, nil
}

