func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
	if strings.TrimSpace(output) != "" {
		if pushErr != nil {
			logging.Debug(ctx, "git push failed",
				slog.String("error", pushErr.Error()),
				slog.String("output", output),
