 88	func reconcileOversizedV1ForPush(
 89		ctx context.Context,
 90		repo *git.Repository,
 91		observedLocalTip, remoteTip plumbing.Hash,
 92		threshold int64,
 93	) (plumbing.Hash, bool, error) {
 94		if observedLocalTip.IsZero() {
 95			return observedLocalTip, false, nil
 96		}
 97	
 98		mergeBase := plumbing.ZeroHash
 99		if !remoteTip.IsZero() {
100			var err error
101			mergeBase, err = computeMergeBase(repo, observedLocalTip, remoteTip)
102			if err != nil {
103				return plumbing.ZeroHash, false, fmt.Errorf("compute original merge-base: %w", err)
104			}
105		}
106		hasOversizedLocalHistory, err := hasOversizedMetadataIntroducedSince(
107			ctx, repo, observedLocalTip, mergeBase, threshold,
108		)
109		if err != nil {
110			return plumbing.ZeroHash, false, err
111		}
112		if !hasOversizedLocalHistory {
113			return observedLocalTip, false, nil
114		}
115	
116		rewriter := newMetadataRewriter(ctx, repo, threshold)
117		rewrittenTip, err := rewriter.rewriteHistory(observedLocalTip)
118		if err != nil {
119			return plumbing.ZeroHash, false, fmt.Errorf("rewrite oversized local metadata: %w", err)
120		}
121		if rewriter.commitsRewritten == 0 {
122			return observedLocalTip, false, nil
123		}
124		if remoteTip.IsZero() {
125			if err := atomicSetV1Ref(ctx, repo, observedLocalTip, rewrittenTip); err != nil {
126				return plumbing.ZeroHash, false, err
127			}
128			return rewrittenTip, true, nil
129		}
130	
131		rewrittenBoundary, originalBoundary, found, err := findSharedRewrittenTree(
132			ctx, repo, rewrittenTip, remoteTip, rewriter.commits,
133		)
134		if err != nil {
135			return plumbing.ZeroHash, false, err
136		}
137		if !found {
138			return observedLocalTip, false, nil
139		}
140	
141		if !mergeBase.IsZero() {
142			safe, err := boundaryAtOrAfterMergeBase(repo, mergeBase, originalBoundary)
143			if err != nil {
144				return plumbing.ZeroHash, false, err
145			}
146			if !safe {
147				return observedLocalTip, false, nil
148			}
149		}
150	
151		repoPath, err := getRepoPath(repo)
152		if err != nil {
153			return plumbing.ZeroHash, false, fmt.Errorf("get repository path: %w", err)
154		}
155		localOnly, err := collectCommitsSince(ctx, repo, repoPath, rewrittenTip, rewrittenBoundary)
156		if err != nil {
157			return plumbing.ZeroHash, false, fmt.Errorf("collect local checkpoints after repaired boundary: %w", err)
158		}
159	
160		newTip := remoteTip
161		if len(localOnly) > 0 {
162			shallow, shallowErr := loadShallowHashes(ctx, repoPath)
163			if shallowErr != nil {
164				return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", shallowErr)
165			}
166			newTip, err = cherryPickOnto(ctx, repo, remoteTip, localOnly, shallow)
167			if err != nil {
168				return plumbing.ZeroHash, false, fmt.Errorf("replay local checkpoints onto repaired remote: %w", err)
169			}
170		}
171	
172		if err := atomicSetV1Ref(ctx, repo, observedLocalTip, newTip); err != nil {
173			return plumbing.ZeroHash, false, err
174		}
175		return newTip, true, nil
176	}
