178	func hasOversizedMetadataIntroducedSince(
179		ctx context.Context,
180		repo *git.Repository,
181		tip, boundary plumbing.Hash,
182		threshold int64,
183	) (bool, error) {
184		repoPath, err := getRepoPath(repo)
185		if err != nil {
186			return false, fmt.Errorf("get repository path for metadata scan: %w", err)
187		}
188		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
189		defer cancel()
190	
191		rangeSpec := tip.String()
192		if !boundary.IsZero() {
193			rangeSpec = boundary.String() + ".." + tip.String()
194		}
195		countCmd := exec.CommandContext(ctx, "git", "rev-list", "--count", rangeSpec)
196		countCmd.Dir = repoPath
197		countOut, err := countCmd.Output()
198		if err != nil {
199			return false, fmt.Errorf("count local checkpoints after merge-base: %w", err)
200		}
201		count, err := strconv.Atoi(strings.TrimSpace(string(countOut)))
202		if err != nil {
203			return false, fmt.Errorf("parse checkpoint history length: %w", err)
204		}
205		if count > MaxCommitTraversalDepth {
206			return false, fmt.Errorf("checkpoint metadata scan exceeded %d commits", MaxCommitTraversalDepth)
207		}
208	
209		objectsCmd := exec.CommandContext(ctx, "git", "rev-list", "--objects", rangeSpec)
210		objectsCmd.Dir = repoPath
211		objectsOut, err := objectsCmd.Output()
212		if err != nil {
213			return false, fmt.Errorf("list local checkpoint metadata objects: %w", err)
214		}
215		seen := make(map[plumbing.Hash]struct{})
216		for _, line := range strings.Split(string(objectsOut), "\n") {
217			if err := ctx.Err(); err != nil {
218				return false, fmt.Errorf("scan local checkpoint metadata: %w", err)
219			}
220			fields := strings.SplitN(line, " ", 2)
221			if len(fields) != 2 || path.Base(fields[1]) != paths.MetadataFileName {
222				continue
223			}
224			hash := plumbing.NewHash(fields[0])
225			if _, exists := seen[hash]; exists {
226				continue
227			}
228			seen[hash] = struct{}{}
229			blob, err := repo.BlobObject(hash)
230			if err != nil {
231				return false, fmt.Errorf("load metadata blob %s at %s: %w", hash, fields[1], err)
232			}
233			if blob.Size > threshold {
234				return true, nil
235			}
584	type metadataRewriter struct {
585		ctx       context.Context //nolint:containedctx // scoped to one rewrite; threaded into commit signing
586		repo      *git.Repository
587		threshold int64
588	
589		blobs   map[plumbing.Hash]plumbing.Hash
590		trees   map[plumbing.Hash]plumbing.Hash
591		commits map[plumbing.Hash]plumbing.Hash
592	
593		commitsRewritten int
594		blobsShrunk      int
595		stillOversized   []OversizedMetadataBlob
596	}
597	
598	func newMetadataRewriter(ctx context.Context, repo *git.Repository, threshold int64) *metadataRewriter {
599		return &metadataRewriter{
600			ctx:       ctx,
601			repo:      repo,
602			threshold: threshold,
603			blobs:     make(map[plumbing.Hash]plumbing.Hash),
604			trees:     make(map[plumbing.Hash]plumbing.Hash),
605			commits:   make(map[plumbing.Hash]plumbing.Hash),
606		}
607	}
608	
609	// rewriteHistory returns the rewritten equivalent of tip. Parents are processed
610	// before children with an explicit stack, so a branch with thousands of
611	// checkpoints does not recurse thousands deep.
612	func (r *metadataRewriter) rewriteHistory(tip plumbing.Hash) (plumbing.Hash, error) {
613		if tip.IsZero() {
614			return tip, nil
615		}
616		type frame struct {
617			hash     plumbing.Hash
618			expanded bool
619		}
620		stack := []frame{{hash: tip}}
621		for len(stack) > 0 {
622			if err := r.ctx.Err(); err != nil {
623				return plumbing.ZeroHash, err //nolint:wrapcheck // context cancellation propagates as-is
624			}
625			top := len(stack) - 1
626			f := stack[top]
627			if _, done := r.commits[f.hash]; done {
628				stack = stack[:top]
629				continue
630			}
631			c, err := r.repo.CommitObject(f.hash)
632			if err != nil {
633				return plumbing.ZeroHash, fmt.Errorf("load commit %s: %w", f.hash, err)
634			}
635			if !f.expanded {
636				stack[top].expanded = true
637				for _, p := range c.ParentHashes {
638					if _, done := r.commits[p]; !done {
639						stack = append(stack, frame{hash: p})
640					}
641				}
642				continue
643			}
644			newHash, err := r.rewriteCommit(c)
645			if err != nil {
646				return plumbing.ZeroHash, err
647			}
648			r.commits[f.hash] = newHash
649			stack = stack[:top]
650		}
651		return r.commits[tip], nil
652	}
653	
654	func (r *metadataRewriter) rewriteCommit(c *object.Commit) (plumbing.Hash, error) {
655		newTree, err := r.rewriteTree(c.TreeHash, "")
656		if err != nil {
657			return plumbing.ZeroHash, err
658		}
659		parents := make([]plumbing.Hash, 0, len(c.ParentHashes))
660		changed := !newTree.Equal(c.TreeHash)
661		for _, p := range c.ParentHashes {
662			np, ok := r.commits[p]
663			if !ok {
664				return plumbing.ZeroHash, fmt.Errorf("parent %s of %s was not rewritten first", p, c.Hash)
665			}
666			if !np.Equal(p) {
667				changed = true
668			}
669			parents = append(parents, np)
670		}
671		if !changed {
672			return c.Hash, nil
673		}
674		rewritten := &object.Commit{
675			Author:       c.Author,
676			Committer:    c.Committer,
677			Message:      c.Message,
678			TreeHash:     newTree,
679			ParentHashes: parents,
680			Encoding:     c.Encoding,
681			ExtraHeaders: c.ExtraHeaders,
682		}
683		// Re-sign when signing is configured: the original signature covered the
684		// original tree, so it cannot be carried over. Signing makes the rewritten
685		// hash non-deterministic across runs, which is why reconciliation below
686		// compares trees (contentReachable) rather than hashes.
687		checkpoint.SignCommitBestEffort(r.ctx, rewritten)
688		obj := r.repo.Storer.NewEncodedObject()
689		if err := rewritten.Encode(obj); err != nil {
690			return plumbing.ZeroHash, fmt.Errorf("encode rewritten commit %s: %w", c.Hash, err)
646		if mergeBase == "" {
647			return plumbing.ZeroHash, errNoMergeBase
648		}
649		return plumbing.NewHash(mergeBase), nil
650	}
651	
652	// collectCommitsSince returns non-merge commits reachable from tip but not from
653	// exclude, ordered oldest-first in topological order.
654	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
655		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
656		defer cancel()
657	
658		// cherryPickOnto computes each commit's delta against its first parent, so
659		// replaying merge commits would incorrectly re-apply changes that arrived via
660		// non-first-parent history. Limit the replay set to non-merge commits.
661		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
662		cmd.Dir = repoPath
663		output, err := cmd.Output()
664		if err != nil {
665			return nil, fmt.Errorf("git rev-list failed: %w", err)
666		}
667	
668		lines := strings.Fields(string(output))
669		if len(lines) > MaxCommitTraversalDepth {
670			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
671		}
672	
673		commits := make([]*object.Commit, 0, len(lines))
674		for _, line := range lines {
675			hash := plumbing.NewHash(line)
676			commit, commitErr := repo.CommitObject(hash)
677			if commitErr != nil {
678				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
679			}
680			if len(commit.ParentHashes) > 1 {
681				continue
682			}
683			commits = append(commits, commit)
684		}
112		// branch — the empty-remote guard below is unnecessary for this backend.
113		// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
114		// push for downgrade safety is a later step.)
115		if ps.primaryIsRefs {
116			return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
117		}
118	
119		// git-branch primary: entire/checkpoints/v1 is a real refs/heads branch, so
120		// on an otherwise-empty remote a forge like GitHub would select it as the
121		// default. Defer publication until the user's own branch exists there.
122		deferAutomaticCheckpointPush := protectFirstUserBranch && deferCheckpointPushOnEmptyRemote(ctx, ps)
123	
124		refs := checkpoint.ResolveRefs(ctx)
125		repo, repoErr := OpenRepository(ctx)
126		if repoErr != nil {
127			logging.Warn(ctx, "checkpoint policy pre-push: failed to open repository; allowing checkpoint push",
128				slog.String("error", repoErr.Error()),
129			)
130		} else {
131			defer repo.Close()
132			syncCheckpointPolicyForPrePush(ctx, repo, ps)
133			if !checkpointPolicyAllowsGitHook(ctx, repo) {
134				// Policy failures should skip checkpoint pushes, not abort the user's push.
135				return nil
136			}
137			if err := prepareOversizedV1ForPush(
138				ctx, repo, ps.pushTarget(), OversizedCheckpointMetadataThreshold,
139			); err != nil {
140				logging.Warn(ctx, "checkpoint metadata cleanup failed; continuing without it",
141					slog.String("error", err.Error()),
142				)
143			}
144		}
145	
146		// OPF pre-push rewrite: if OPF is configured, resolve the user's
147		// decision (env > settings > prompt > non-TTY auto-run), then
148		// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
149		// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
150		// so the common-case fast path is unchanged.
151		if redact.OPFEnabled() {
152			decision, decisionErr := opfPrePushDecision(ctx)
153			if decisionErr != nil {
154				logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
155					slog.String("error", decisionErr.Error()),
156				)
157				return decisionErr
158			}

