652	// collectCommitsSince returns non-merge commits reachable from tip but not from
653	// exclude, ordered oldest-first in topological order.
654	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
655		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
656		defer cancel()
657	
658		// cherryPickOnto computes each commit's delta against its first parent, so
659		// replaying merge commits would incorrectly re-apply changes that arrived via
660		// non-first-parent history. Limit the replay set to non-merge commits.
661		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
662		cmd.Dir = repoPath
663		output, err := cmd.Output()
664		if err != nil {
665			return nil, fmt.Errorf("git rev-list failed: %w", err)
666		}
667	
668		lines := strings.Fields(string(output))
669		if len(lines) > MaxCommitTraversalDepth {
670			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
671		}
672	
673		commits := make([]*object.Commit, 0, len(lines))
674		for _, line := range lines {
675			hash := plumbing.NewHash(line)
676			commit, commitErr := repo.CommitObject(hash)
677			if commitErr != nil {
678				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
679			}
680			if len(commit.ParentHashes) > 1 {
681				continue
682			}
683			commits = append(commits, commit)
684		}
112		// branch — the empty-remote guard below is unnecessary for this backend.
113		// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
114		// push for downgrade safety is a later step.)
115		if ps.primaryIsRefs {
116			return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
117		}
118	
119		// git-branch primary: entire/checkpoints/v1 is a real refs/heads branch, so
120		// on an otherwise-empty remote a forge like GitHub would select it as the
121		// default. Defer publication until the user's own branch exists there.
122		deferAutomaticCheckpointPush := protectFirstUserBranch && deferCheckpointPushOnEmptyRemote(ctx, ps)
123	
124		refs := checkpoint.ResolveRefs(ctx)
125		repo, repoErr := OpenRepository(ctx)
126		if repoErr != nil {
127			logging.Warn(ctx, "checkpoint policy pre-push: failed to open repository; allowing checkpoint push",
128				slog.String("error", repoErr.Error()),
129			)
130		} else {
131			defer repo.Close()
132			syncCheckpointPolicyForPrePush(ctx, repo, ps)
133			if !checkpointPolicyAllowsGitHook(ctx, repo) {
134				// Policy failures should skip checkpoint pushes, not abort the user's push.
135				return nil
136			}
137			if err := prepareOversizedV1ForPush(
138				ctx, repo, ps.pushTarget(), OversizedCheckpointMetadataThreshold,
139			); err != nil {
140				logging.Warn(ctx, "checkpoint metadata cleanup failed; continuing without it",
141					slog.String("error", err.Error()),
142				)
143			}
144		}
145	
146		// OPF pre-push rewrite: if OPF is configured, resolve the user's
147		// decision (env > settings > prompt > non-TTY auto-run), then
148		// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
149		// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
150		// so the common-case fast path is unchanged.
151		if redact.OPFEnabled() {
152			decision, decisionErr := opfPrePushDecision(ctx)
153			if decisionErr != nil {
154				logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
155					slog.String("error", decisionErr.Error()),
156				)
157				return decisionErr
158			}

